	["QuestData"] = {
		["EN"] = {
			[1] = {
				questName = "Nicotine in the Apocalypse",
				questDescription = "In a world of unrelenting chaos, even the simplest comforts become precious. A desperate survivor clings to a fading habit – cigarettes – to stay alive. Collect 25 cigarettes to bring him solace.",
				questRewards = "5 Skill Points\n250 XP\n$25\n1x Cigar\n25x Brain Matter"
			},
			[2] = {
				questName = "Fuel of Hope",
				questDescription = "Amid the devastation, fuel remains the lifeblood of survival. A stranded mechanic urgently needs oil and gasoline to keep his vehicle running. Secure 5 units each to spark hope.",
				questRewards = "5 Skill Points\n250 XP\n$25\n1x Repair Kit\n25x Brain Matter"
			},
			[3] = {
				questName = "Tools of Survival",
				questDescription = "Survival depends on the right tools. A clever engineer in the camp needs 25 wrenches to repair critical equipment. Venture into the wasteland and collect them to restore order.",
				questRewards = "10 Skill Points\n500 XP\n$250\n10x Brain Matter"
			},
			[4] = {
				questName = "Badges and Batons",
				questDescription = "Law and order collapsed after the catastrophe. An old police veteran clings to his past and asks you to recover 5 police badges and 10 batons from the ruins of fallen comrades.",
				questRewards = "25 Skill Points\n2500 XP\n$500\nPolice Uniform\nPolice Station Key\n100x Brain Matter"
			},
			[5] = {
				questName = "The Stolen Freeway",
				questDescription = "A Freeway, stolen in the chaos, now lies abandoned in Zone 11. Retrieve it and restore a vital traffic artery to reignite the pulse of civilization.",
				questRewards = "10 Skill Points\n500 XP\n$125\nFarmer Outfit\nDillimore’s Hope – Backroom Key\nSpawn Point: Crazy Joe’s Farm\n25x Brain Matter"
			},
			[6] = {
				questName = "Secrets of the Lost Collection",
				questDescription = "In a forgotten corner of the apocalypse, the treasured artifacts of an eccentric collector have vanished. Venture into the neon-lit ruins of the old city to recover 50 rare collectibles and bring order to chaos.",
				questRewards = "25 Skill Points\n2500 XP\n$500\nSpecial Outfit\nBackdoor Key to the Gas Station\n100x Brain Matter"
			},
			[7] = {
				questName = "Evidence of the Truth",
				questDescription = "Rumors suggest the government once released a deadly virus. Lost cameras might reveal the truth. Gather the scattered devices – even those from fallen comrades turned monsters.",
				questRewards = "25 Skill Points\n2500 XP\n$500\nCamera Crafting Recipe\n100x Brain Matter\n"
			},
			[8] = {
				questName = "Wrenches of the Wasteland",
				questDescription = "Search gas stations and abandoned workshops for 150 wrenches to ensure survival machines keep running.",
				questRewards = "25 Skill Points\n2500 XP\n$500\nMechanic Outfit\n100x Brain Matter"
			},
			[9] = {
				questName = "The Stolen Sanchez",
				questDescription = "A beloved classic – the Sanchez – was stolen and left behind in this zone. Retrieve this lost relic and return it to its rightful owner to preserve a piece of freedom.",
				questRewards = "10 Skill Points\n500 XP\n$125\nPay 'N' Spray Locations\nSpawn Point: Blueberry Zone\n25x Brain Matter"
			},
			[10] = {
				questName = "Pizza Rescue",
				questDescription = "Abandoned pizzerias in San Andreas still hold unopened pizza boxes. Follow map clues to these forgotten places and collect 50 pizzas to revive the taste of a bygone era.",
				questRewards = "50 Skill Points\n5000 XP\n$625\nKnife Crafting Recipe\n125x Brain Matter"
			},
			[11] = {
				questName = "Legacy of the Fire Department",
				questDescription = "Among the rubble, a hero's legacy lives on. Collect 50 fire helmets from the charred remains of stations to unlock the secret fire extinguisher crafting recipe.",
				questRewards = "50 Skill Points\n2500 XP\n$625\nFire Extinguisher Crafting Recipe\n125x Brain Matter"
			},
			[12] = {
				questName = "Emergency Supplies",
				questDescription = "Leftover medical supplies linger in abandoned hospitals. Collect 50 bandages from these places to reveal the recipe for a crucial first aid kit.",
				questRewards = "25 Skill Points\n2500 XP\n$500\nFirst Aid Kit Recipe\n100x Brain Matter"
			},
			[13] = {
				questName = "The Fabric Factory",
				questDescription = "Once-bustling clothing stores now lie in ruins, their fabric remnants scattered on the streets. Collect 50 pieces to obtain the key to an old factory where new garments rise from the ashes.",
				questRewards = "65 Skill Points\n6250 XP\n$1250\nClothing Factory Key\n175x Brain Matter"
			},
			[14] = {
				questName = "The Tattoo Studio",
				questDescription = "Art endures even in the wasteland. Find 50 units of tattoo ink hidden in abandoned studios to unlock the secret key to a legendary tattoo parlor.",
				questRewards = "65 Skill Points\n6250 XP\n$1250\nTattoo Studio Key\n175x Brain Matter"
			},
			[15] = {
				questName = "Reviving the Barber Shop",
				questDescription = "Beauty is a rare treasure in these dark times. Search abandoned barber shops for 50 scissors to secure the key to a reborn era of style.",
				questRewards = "65 Skill Points\n6250 XP\n$1250\nBarber Shop Key\n175x Brain Matter"
			},
			[16] = {
				questName = "Dynamite Demolition",
				questDescription = "When strategy fails, raw force prevails. Destroy 10 zombie nests to obtain the coveted dynamite crafting recipe – a tool as devastating as it is essential.",
				questRewards = "75 Skill Points\n8500 XP\n$1500\nDynamite Crafting Recipe\n250x Brain Matter"
			},
			[17] = {
				questName = "Tuning Expert",
				questDescription = "Precision and speed mean the difference between life and death. Eliminate 500 infected enemies to reveal the location of the special engine workshop and turn vehicles into survival machines.",
				questRewards = "75 Skill Points\n8500 XP\n$1250\nTuning Garage Locations\n175x Brain Matter"
			},
			[18] = {
				questName = "Prison Break",
				questDescription = "Deep within the crumbling walls of an abandoned prison, echoes of rebellion still linger. Uncover the secrets hidden within.",
				questRewards = "30 Skill Points\n1500 XP\n$125\n175x Brain Matter"
			},
			[19] = {
				questName = "Fire Against Steel",
				questDescription = "The army’s unethical experiments birthed armored giants. Destroy 15 enemy tanks using molotovs or a flamethrower to prove that even steel can't escape the inferno.",
				questRewards = "30 Skill Points\n2000 XP\n$300\n100x Brain Matter"
			},
			[20] = {
				questName = "Mission: Moonflight",
