		["DE"] = {
			[1] = {
				questName = "Nikotin in der Apokalypse",
				questDescription = "In einer Welt unaufhörlichen Chaos' werden selbst die einfachsten Annehmlichkeiten kostbar. Ein verzweifelter Überlebender klammert sich mit einer schwindenden Gewohnheit – Zigaretten – ans Leben. Sammle 25 Zigaretten, um ihm Trost zu spenden.",
				questRewards = "5 Fähigkeitspunkte\n250 Erfahrungspunkte\n$25\n1x Zigarre\n25x Gehirnmasse"
			},
			[2] = {
				questName = "Treibstoff der Hoffnung",
				questDescription = "Mitten in der Verwüstung bleibt Treibstoff das Lebenselixier des Überlebens. Ein gestrandeter Mechaniker benötigt dringend Öl und Benzin, um sein Fahrzeug am Laufen zu halten. Sichere je 5 Einheiten, um einen Funken Hoffnung zu liefern.",
				questRewards = "5 Fähigkeitspunkte250 Erfahrungspunkte\n$25\n1x Reparaturset\n25x Gehirnmasse"
			},
			[3] = {
				questName = "Werkzeuge des Überlebens",
				questDescription = "Das Überleben hängt von den richtigen Werkzeugen ab. Ein findiger Ingenieur im Lager benötigt 25 Schraubenschlüssel, um kritische Ausrüstung zu reparieren. Wage dich in die Ödnis und sammle sie, um die Ordnung wiederherzustellen.",
				questRewards = "10 Fähigkeitspunkte\n500 Erfahrungspunkte\n$250\n10x Gehirnmasse"
			},
			[4] = {
				questName = "Abzeichen und Schlagstöcke",
				questDescription = "Nach der Katastrophe sind Gesetz und Ordnung zerfallen. Ein alter Polizeiveteran klammert sich an die Überreste seiner Vergangenheit und bittet dich, 5 Polizeiabzeichen und 10 Schlagstöcke aus den Ruinen gefallener Kollegen zu bergen.",
				questRewards = "25 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$500\nPolizeiuniform\nSchlüssel zur Polizeidienststelle\n100x Gehirnmasse"
			},
			[5] = {
				questName = "Die gestohlene Freeway",
				questDescription = "Eine Freeway, gestohlen im Chaos, liegt nun verlassen in Zone 11. Hole sie zurück und stelle eine wichtige Verkehrsader wieder her, um den Puls der Zivilisation neu zu entfachen.",
				questRewards = "10 Fähigkeitspunkte\n500 Erfahrungspunkte\n$125\nBauernoutfit\nDillimores Hoffnung – Schlüssel zu den Hinterzimmern\nSpawnpunkt: Crazy Joe's Farm\n25x Gehirnmasse"
			},
			[6] = {
				questName = "Die Geheimnisse der verlorenen Sammlung",
				questDescription = "In einer vergessenen Ecke der Apokalypse sind die wertvollen Artefakte eines exzentrischen Sammlers verschwunden. Wage dich in die neonbeleuchteten Ruinen der alten Stadt, um 50 seltene Sammlerstücke zu bergen und das Chaos zu ordnen.",
				questRewards = "25 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$500\nSonderoutfit\nSchlüssel zur Hintertür der Tankstelle\n100x Gehirnmasse"
			},
			[7] = {
				questName = "Beweise der Wahrheit",
				questDescription = "Gerüchte besagen, dass die Regierung einst ein tödliches Virus freigesetzt hat. Verloren gegangene Kameras könnten die Wahrheit offenbaren. Sammle die verstreuten Geräte – selbst jene von gefallenen Kollegen, die zu Monstern wurden.",
				questRewards = "25 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$500\nKamera-Herstellungsrezept\n100x Gehirnmasse"
			},
			[8] = {
				questName = "Schraubenschlüssel der Ödnis",
				questDescription = "Durchsuche Tankstellen und verlassene Werkstätten nach 150 Schraubenschlüsseln, um sicherzustellen, dass die Überlebensmaschinen weiterhin funktionieren.",
				questRewards = "25 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$500\nMechaniker-Outfit\n100x Gehirnmasse"
			},
			[9] = {
				questName = "Der gestohlene Sanchez",
				questDescription = "Ein geliebter Klassiker – die Sanchez – wurde gestohlen und in dieser Zone zurückgelassen. Hole dieses verlorene Relikt zurück und gib es seinem rechtmäßigen Besitzer, um ein Stück Freiheit zu bewahren.",
				questRewards = "10 Fähigkeitspunkte\n500 Erfahrungspunkte\n$125\nPay 'N' Spray Standorte\nSpawnpunkt: Blueberry Zone\n25x Gehirnmasse"
			},
			[10] = {
				questName = "Die Pizzarettung",
				questDescription = "Verlassene Pizzerien in San Andreas bergen noch ungeöffnete Pizzakartons. Folge den Hinweisen auf deiner Karte zu diesen vergessenen Orten und sammle 50 Pizzen, um den Geschmack einer vergangenen Ära wiederzubeleben.",
				questRewards = "50 Fähigkeitspunkte\n5000 Erfahrungspunkte\n$625\nMesser-Herstellungsrezept\n125x Gehirnmasse"
			},
			[11] = {
				questName = "Das Erbe der Feuerwehr",
				questDescription = "Zwischen den Trümmern lebt das Erbe eines Helden weiter. Sammle 50 Feuerwehrhelme aus den verkohlten Überresten von Stationen, um das geheime Rezept für einen lebensrettenden Feuerlöscher freizuschalten.",
				questRewards = "50 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$625\nFeuerlöscher-Herstellungsrezept\n125x Gehirnmasse"
			},
			[12] = {
				questName = "Notfallversorgung",
				questDescription = "In verlassenen Krankenhäusern verweilen noch Reste medizinischer Versorgung. Sammle 50 Verbände von diesen verlassenen Orten, um das Rezept für einen wichtigen Erste-Hilfe-Kasten zu enthüllen.",
				questRewards = "25 Fähigkeitspunkte\n2500 Erfahrungspunkte\n$500\nErste-Hilfe-Kasten-Rezept\n100x Gehirnmasse"
			},
			[13] = {
				questName = "Die Stofffabrik",
				questDescription = "Einst pulsierende Bekleidungsgeschäfte liegen nun in Trümmern, ihre Stoffreste auf den Straßen verstreut. Sammle 50 Stück, um den Schlüssel zu einer alten Fabrik zu sichern, in der aus der Asche neue Gewänder entstehen.",
				questRewards = "65 Fähigkeitspunkte\n6250 Erfahrungspunkte\n$1250\nSchlüssel zur Bekleidungsfabrik\n175x Gehirnmasse"
			},
			[14] = {
				questName = "Das Tattoo-Studio",
				questDescription = "Die Kunst überdauert selbst in der Einöde. Finde 50 Einheiten Tattoo-Tinte, versteckt in verlassenen Studios, um den geheimen Schlüssel zu einem legendären Tattoostudio freizuschalten.",
				questRewards = "65 Fähigkeitspunkte\n6250 Erfahrungspunkte\n$1250\nSchlüssel zum Tattoostudio\n175x Gehirnmasse"
			},
			[15] = {
				questName = "Die Wiederbelebung des Friseursalons",
				questDescription = "Die Schönheit ist in diesen dunklen Zeiten ein seltener Schatz. Durchsuche verlassene Friseursalons nach 50 Scheren, um den Schlüssel zur Wiederbelebung einer vergangenen Stilära zu sichern.",
				questRewards = "65 Fähigkeitspunkte\n6250 Erfahrungspunkte\n$1250\nSchlüssel zum Friseursalon\n175x Gehirnmasse"
			},
			[16] = {
				questName = "Dynamit-Demolierung",
				questDescription = "Wenn Strategie versagt, siegt rohe Kraft. Zerstöre 10 Zombie-Nester, um das begehrte Rezept für Dynamit zu erlangen – ein Werkzeug, das ebenso verheerend wie unentbehrlich ist.",
				questRewards = "75 Fähigkeitspunkte\n8500 Erfahrungspunkte\n$1500\nDynamit-Herstellungsrezept\n250x Gehirnmasse"
			},
			[17] = {
				questName = "Tuning-Experte",
				questDescription = "Präzision und Geschwindigkeit sind der Unterschied zwischen Leben und Tod. Eliminiere 500 infizierte Gegner, um den Standort der Spezial Motoren Werkstatt zu enthüllen und Fahrzeuge in Überlebensmaschinen zu verwandeln.",
				questRewards = "75 Fähigkeitspunkte\n8500 Erfahrungspunkte\n$1250\nStandorte der Tuning-Garagen\n175x Gehirnmasse"
			},
			[18] = {
				questName = "Ausbruch aus dem Gefängnis",
				questDescription = "Tief in den bröckelnden Mauern eines verlassenen Gefängnisses hallen noch die Echos der Rebellion. Enthülle die dort verborgenen Geheimnisse.",
				questRewards = "30 Fähigkeitspunkte\n1500 Erfahrungspunkte\n$125\n175x Gehirnmasse"
			},
			[19] = {
				questName = "Feuer gegen Stahl",
				questDescription = "Die unethischen Experimente der Armee haben gepanzerte Giganten hervorgebracht. Vernichte 15 feindliche Panzer mit Molotowcocktails oder einem Flammenwerfer, um zu beweisen, dass selbst Stahl dem Inferno nicht entkommen kann.",
				questRewards = "30 Fähigkeitspunkte\n2000 Erfahrungspunkte\n$300\n100x Gehirnmasse"
			},
			[20] = {
				questName = "Mission: Mondflug",
				questDescription = "Trotz der Verwüstung richtet sich der Blick der Menschheit gen Himmel. Eine nahezu vollständige Rakete wartet auf die fehlenden Teile. Durchsuche die Ödnis und liefere die essenziellen Komponenten, um eine neue Ära einzuläuten.",
				questRewards = "200 Fähigkeitspunkte\n20000 Erfahrungspunkte\n$4250\nRaketen-Benzinkanister\n1000x Gehirnmasse"
			},
			[21] = {
				questName = "Fahrzeugbergungsoperation",
				questDescription = "In einer zerbrochenen Gesellschaft wird jedes Fahrzeug zur Lebensader. Setze einen Abschleppwagen ein, um 25 verlassene Fahrzeuge zu bergen und so den Wiederaufbau der Zivilisation anzustoßen.",
				questRewards = "100 Fähigkeitspunkte\n12500 Erfahrungspunkte\n$2000\nAbschleppwagen-Upgrade-Token\n350x Gehirnmasse"
			},
			[22] = {
