				questDescription = "Finde 25 Schätze und erhalte einen Marquis, mit dem du deinen Suchradius bestimmen und große Mengen Fische fangen kannst.",
				questRewards = "100 Skillpunkte\n22500 Erfahrungspunkte\n$2500\nMarquis\n500x Gehirnmasse",
			},
			[23] = {
