			},
			[38] = {
				questName = "Hirnmasse für die Mutigen",
				questDescription = "Ein Feldmediziner untersucht Zombie-Überreste, um herauszufinden, wie sich die Infektion verbreitet. Sammle 5 Hirnmasse und bringe sie zurück, bevor die nächste Horde eintrifft.",
