		["RU"] = {
			[1] = {
				questName = "Никотин в Апокалипсисе",
				questDescription = "В мире бесконечного хаоса даже самые простые удовольствия становятся драгоценными. Отчаявшийся выживший цепляется за исчезающую привычку — сигареты — чтобы остаться в живых. Соберите 25 сигарет, чтобы принести ему утешение.",
				questRewards = "5 Очков Навыков\n250 XP\n$25\n1x Сигара\n25x Мозговое вещество"
			},
			[2] = {
				questName = "Топливо Надежды",
				questDescription = "Среди разрушений топливо остаётся жизненной силой выживания. Застрявшему механику срочно нужны масло и бензин, чтобы поддерживать свой транспорт. Доставьте по 5 единиц каждого, чтобы зажечь надежду.",
				questRewards = "5 Очков Навыков\n250 XP\n$25\n1x Ремонтный набор\n25x Мозговое вещество"
			},
			[3] = {
				questName = "Инструменты Выживания",
				questDescription = "Выживание зависит от правильных инструментов. Умному инженеру в лагере нужно 25 гаечных ключей для ремонта критического оборудования. Отправляйтесь в пустошь и соберите их, чтобы восстановить порядок.",
				questRewards = "10 Очков Навыков\n500 XP\n$250\n10x Мозговое вещество"
			},
			[4] = {
				questName = "Знаки и Дубинки",
				questDescription = "Закон и порядок рухнули после катастрофы. Старый полицейский ветеран держится за прошлое и просит вас собрать 5 полицейских значков и 10 дубинок с останков павших товарищей.",
				questRewards = "25 Очков Навыков\n2500 XP\n$500\nПолицейская форма\nКлюч от участка\n100x Мозговое вещество"
			},
			[5] = {
				questName = "Украденный Freeway",
				questDescription = "Freeway, украденный в хаосе, теперь заброшен в Зоне 11. Верните его и восстановите важную транспортную артерию, чтобы возродить пульс цивилизации.",
				questRewards = "10 Очков Навыков\n500 XP\n$125\nКостюм Фермера\nКлюч от задней комнаты Dillimore’s Hope\nТочка спавна: Ферма Crazy Joe\n25x Мозговое вещество"
			},
			[6] = {
				questName = "Секреты Потерянной Коллекции",
