		["PT"] = {
			[1] = {
				questName = "Nicotina no Apocalipse",
				questDescription = "Em um mundo de caos incessante, até os confortos mais simples se tornam preciosos. Um sobrevivente desesperado se apega a um hábito antigo – cigarros – para continuar vivo. Colete 25 cigarros para lhe trazer conforto.",
				questRewards = "5 Pontos de Habilidade\n250 XP\n$25\n1x Charuto\n25x Matéria Cerebral"
			},
			[2] = {
				questName = "Combustível da Esperança",
				questDescription = "Em meio à devastação, combustível é o sangue da sobrevivência. Um mecânico preso precisa urgentemente de óleo e gasolina para manter seu veículo funcionando. Garanta 5 unidades de cada para acender a esperança.",
				questRewards = "5 Pontos de Habilidade\n250 XP\n$25\n1x Kit de Reparo\n25x Matéria Cerebral"
			},
			[3] = {
				questName = "Ferramentas de Sobrevivência",
				questDescription = "A sobrevivência depende das ferramentas certas. Um engenheiro inteligente no acampamento precisa de 25 chaves inglesas para reparar equipamentos críticos. Aventure-se pelo deserto e colete-as para restaurar a ordem.",
				questRewards = "10 Pontos de Habilidade\n500 XP\n$250\n10x Matéria Cerebral"
			},
			[4] = {
				questName = "Distintivos e Cassetetes",
				questDescription = "A lei e a ordem desmoronaram após a catástrofe. Um veterano da polícia se apega ao passado e pede que você recupere 5 distintivos e 10 cassetetes dos colegas caídos.",
				questRewards = "25 Pontos de Habilidade\n2500 XP\n$500\nUniforme Policial\nChave da Delegacia\n100x Matéria Cerebral"
			},
			[5] = {
