				questRewards = "10 Pontos de Habilidade\n500 XP\n$125\nTraje de Fazendeiro\nChave do Porão – Dillimore’s Hope\nPonto de Spawn: Fazenda do Crazy Joe\n25x Matéria Cerebral"
			},
			[6] = {
				questName = "Segredos da Coleção Perdida",
